insert into public.cpl_memory (slug,kind,title,summary,tags,status,source,verified_by,verified_at,author,event_date) values
('d-main-red-check-line-stays-out-s690','decision','The Library check line stays out of reading text and new pieces','S690 conductor: main was red from 653864b7. The Library check run''s first pass (run 44733588776) stamped every page''s accessibility line, the starter''s too, so ELL IET''s reading text went from 33,996 to 34,078 characters, past Sierra''s 34,000, and new pieces copied the starter''s line. #3600 (9fc88a07) skips the line in all three readers and drops it from new pieces. Not deployed.',array['library','sierra','ci'],'proposed','#3600','SkyMerlin (S690), the conductor',null,'SkyMerlin (S690)',date '2026-11-20'),
('d-mid-ranking-orders-lane-1-s690','decision','Lane 1 ordered by the M-ID cards each fix unblocks','S690 conductor, under Sam''s Nov 20 work order: a read-only count over the committed files (12:22Z; 49,558 live cards) put City College of San Francisco''s outlines first: 2,065 cards improved, 1,020 completed, 1,401 given first text. The next six have no public outline system or are blocked. Program records feed no M-ID card, so they ran as the second tier.',array['conductor','m-id','collection'],'proposed','docs/session_691_handoff.md','SkyMerlin (S690), the conductor',null,'SkyMerlin (S690)',date '2026-11-20'),
('d-carryovers-closed-for-cap-s690','decision','S689''s carry-overs closed with pointers to hold the three-PR cap','S690 conductor: #3593 (Berkeley City''s Cal-GETC 34) and #3597 (a shared no-ending address) were closed with pointers (comments 7039647197, 7039648134) to keep within three open PRs. Both fold into the night''s one follow-up PR (claude/s690-follow-up) with the minor findings of #3586, #3590, #3594 and #3601, per Sam''s collection-first ruling.',array['conductor','merge','follow-up'],'proposed','#3593; #3597','SkyMerlin (S690), the conductor',null,'SkyMerlin (S690)',date '2026-11-20'),
('d-course-rows-gzipped-s690','decision','Printed catalog courses are filed gzipped, one file per college','S690 conductor: the printed courses read under Sam''s Nov 20 go are filed as kb/hand_filed_catalogs/courses/<slug>.json.gz (gzip -9n, 3.9 MB from 29.6 MB) with index.json, which carries each file''s sha256 of the JSON inside, and a README. Reversible: the plain JSON can be filed instead.',array['catalog-harvest','repo-size','hand-filed'],'proposed','#3604','SkyMerlin (S690), the conductor',null,'SkyMerlin (S690)',date '2026-11-20'),
('d-noce-stays-on-outline-hunt-s690','decision','North Orange Continuing Education stays on the outline hunt','S690 conductor: North Orange''s catalog now reads on the runner (1,089 printed courses), but its SLOs and objectives sit in CurricUNET, which blocks bots, so it stays on the outline hunt. The worker''s hunt record was not filed: the hunt file belongs to the plain session.',array['course-outcomes','noce','hunt'],'proposed','#3584 comment 7042043701; docs/session_691_handoff.md','SkyMerlin (S690), the conductor',null,'SkyMerlin (S690)',date '2026-11-20'),
('d-reread-gate-same-page-calls-s690','decision','Three moved pages count as the same page at the reread gate','S690 conductor, accepting the reread worker''s calls: a page one PDF page off, an address differing only by a double slash, and a new edition of the same catalog (College of the Canyons'' v2 to v3) count as the same page when each moved page''s coverage is equal or higher.',array['program-requirements','reread','keep-the-better'],'proposed','docs/program_requirements_harvest_lessons.md (S690)','SkyMerlin (S690), the conductor',null,'SkyMerlin (S690)',date '2026-11-20'),
('d-golden-west-stops-after-two-rounds-s690','decision','Golden West''s header correction stopped after two review rounds','S690 conductor: the second reader said do not apply. The write returns one 263 KB value the rollback alone depends on (fix: return ids and an after-fingerprint, joined to paged before-values); filed reads corrected before the write would make a load insert 486 rows, 476 beside a live header, so the write goes first. Plan on claude/s690-goldenwest-header (ae5be1d5); to COBIx.',array['course-outcomes','golden-west','rule-10'],'proposed','claude/s690-goldenwest-header ae5be1d5','SkyMerlin (S690), the conductor',null,'SkyMerlin (S690)',date '2026-11-20'),
('m-ccsf-outlines-loaded-s690','milestone','City College of San Francisco''s outlines loaded, outcomes only','S690: read 44748015052 filed 1,417 pages in two parts (2,904 and 2,900 SLOs, every page 200, none cut); standing test 26 of 26; load 44767903173 inserted 1,416 SLO rows (ids 41769 to 43184; report 28 prints no objectives), receipt kb/receipts/course_outcomes_ccsf_44767903173.json, live count confirmed. Parsed outcomes only, per #3601.',array['course-outcomes','slo','ccsf'],'proposed','#3601; load run 44767903173','SkyMerlin (S690), the conductor',null,'SkyMerlin (S690)',date '2026-11-20'),
('m-reread-and-pages-posts-s690','milestone','35 program records added and 129 replaced by a better reread','S690: the pages levers (Laney, Diablo Valley, Orange Coast; $7.68) and the reread plan''s rows 46 to 55 (Napa Valley, Cerro Coso, Santa Monica, San Diego College of Continuing Education, Mt. San Antonio; $7.89), each kept the better record, posted and loaded: 35 new, 129 replaced, 6 restored, 3 held for a person. Victor Valley, Mt. San Jacinto and Southwestern found no own page.',array['program-requirements','reread','keep-the-better'],'proposed','#3604; docs/program_requirements_harvest_lessons.md (S690)','SkyMerlin (S690), the conductor',null,'SkyMerlin (S690)',date '2026-11-20'),
('m-printed-catalog-courses-s690','milestone','17,341 printed catalog courses filed at 16 colleges','S690, under Sam''s Nov 20 go: the census Reader on the runner read 16 catalogs the nightly script reader could not, for no extraction cost: North Orange, the CourseLeaf four (HTML), the nine LACCD colleges and Clovis (catalog PDFs), and El Camino from Sam''s copy. Fifteen are marked Sky can read in the harvest lane. No pipeline yet fills M-ID card descriptions from them.',array['catalog-harvest','m-id','hand-filed'],'proposed','#3604; kb/hand_filed_catalogs/courses/index.json','SkyMerlin (S690), the conductor',null,'SkyMerlin (S690)',date '2026-11-20'),
('f-waf-answers-runner-and-session-apart-s690','fact','A WAF host served the runner 200 and the cloud session a 202 check','S690: catalog.nocccd.edu and four CourseLeaf hosts served the GitHub runner HTTP 200 with content, while the sandbox and the plain session''s cloud browser got 202 with an AWS WAF check. The committed captures already showed the reader at 200 there. Cite the reader''s own capture for access, never a session''s probe; the reader stops on a check and never retries.',array['catalog-harvest','blocked-sources','sandbox'],'proposed','#3584 comments 7042630940, 7042639554, 7042730508; docs/kb-notes/methodology-a-bot-wall-answers-each-network-on-its-own.md','SkyMerlin (S690), the conductor',null,'SkyMerlin (S690)',date '2026-11-20'),
('f-butte-page-addresses-changed-case-s690','fact','Butte''s catalog addresses changed case and slashes','S690: every Butte page address moved (Catalog//iq to catalog/iq), so the reread''s unchanged() test saw 163 unchanged programs as moved and would have paid about $18 for one aim program. Butte is held until unchanged() and held() compare normalized addresses.',array['program-requirements','reread','butte'],'proposed','docs/program_requirements_harvest_lessons.md (S690)','SkyMerlin (S690), the conductor',null,'SkyMerlin (S690)',date '2026-11-20'),
('f-orange-coast-live-rows-older-run-s690','fact','Orange Coast''s live rows hold an older run than main''s files','S690 pages worker: 109 of Orange Coast''s live program_requirement_records rows hold run 38670927724 where main files 39726645292. Which stands is settled before Orange Coast''s next load.',array['program-requirements','orange-coast','live-rows'],'proposed','S690 pages worker (live reads 44747782378, 44748800216, 44749036108)','SkyMerlin (S690), the conductor',null,'SkyMerlin (S690)',date '2026-11-20'),
('f-ccsf-prior-catalog-refused-s690','fact','City College of San Francisco''s prior-year catalog sits off its challenged pages','S690: rule D''s prior-year read for CCSF''s 27 not-printed programs met a Cloudflare 403 on www.ccsf.edu''s pages and a 404 on the guessed 2025-26 PDF (free preview 44738618128). COBIx found the file under the /2026/ upload folder (#3358 comment 7045033164, sha256 23cc7ed1...): only the HTML pages are challenged, so a runner read of the PDF followed.',array['program-requirements','rule-d','blocked-sources'],'proposed','#3358 comments 7040201320, 7045033164','SkyMerlin (S690), the conductor',null,'SkyMerlin (S690)',date '2026-11-20'),
('f-golden-west-476-header-rows-s690','fact','Golden West carries 476 header rows as outcomes','S690 second reader: 476 Golden West SLO rows carry a header, two more than f-golden-west-474-header-rows-s689 counted (THEA G210 Course Outcome, MUS G111 Couse Outcomes). Coastline ANTH G190 (id 7204) has the same shape, and 4 Golden West rows open with Course Objectives (ELL G015N, ART G145, AUTO G004N, ELL G025N).',array['course-outcomes','golden-west','data-quality'],'proposed','claude/s690-goldenwest-header ae5be1d5','SkyMerlin (S690), the conductor',null,'SkyMerlin (S690)',date '2026-11-20'),
('o-shared-pages-claim-34-programs-s690','opportunity','Shared pathway pages claim 34 programs at two colleges','S690 pages worker: shared pages claim 34 programs that a page read cannot give their own page: 19 at Orange Coast (its shared pathway pages) and 15 at Diablo Valley (claimed by another program''s page). A reader change for shared pages is a possible lever, unmeasured; measure it free before any paid read.',array['program-requirements','reader','pages'],'proposed','docs/program_requirements_harvest_lessons.md (S690)','SkyMerlin (S690), the conductor',null,'SkyMerlin (S690)',date '2026-11-20'),
('p-recall-gate-counts-parser-output-s690','pitfall','A recall gate whose hand counts equal the parser''s checks nothing','S690: #3601''s first review round was BLOCKING. The outline gate''s hand counts equalled len() of the parser''s own outcomes, and it opened on an empty or 403 trial. Round two counted the trial''s SLOs by eye from its job log (12 of 12), bound them to the parser fingerprint d5cef493, and refuses a non-200 or capped page, an unsourced count and a changed fingerprint.',array['course-outcomes','testing','recall'],'proposed','#3601; docs/kb-notes/methodology-a-test-must-not-take-its-rule-as-the-truth.md','SkyMerlin (S690), the conductor',null,'SkyMerlin (S690)',date '2026-11-20'),
('p-workers-hand-back-on-background-wait-s690','pitfall','Workers handed back while their own runs were in flight','S690: workers handed back within six minutes of starting, saying their brief told them to, while their own runs were still running; a SendMessage resumed them. A worker''s brief says to wait on its own runs with a background check and hand back only when they finish.',array['conductor','workers','briefs'],'proposed','docs/reference/conductor_mode.md (S690)','SkyMerlin (S690), the conductor',null,'SkyMerlin (S690)',date '2026-11-20')
insert into public.cpl_memory_log (memory_id, actor, action, note, after)
insert into public.cpl_memory (slug,kind,title,summary,tags,status,source,verified_by,verified_at,author,event_date) values
('r-plain-page-read-blocked-catalogs-sam-2026-11-20','decision','Read the blocked catalogs with a plain page read in the collection wave','Sam, 2026-11-20 6:26 AM PT, relayed by COBIx on #3584 (comment 7042043701): "read these catalogs with a plain, browser-like page read in tonight''s collection wave." An ordinary page request: robots.txt followed, no challenge solved, no 403 retried (COBIx, 7042639554). Each college read so is marked Sky can read and read every night; the morning checkpoint gives a line per college.',array['catalog-harvest','collection','sam-ruling'],'verified','#3584 comment 7042043701','Sam (relayed by COBIx)',now(),'SkyMerlin (S690)',date '2026-11-20')
insert into public.cpl_memory_log (memory_id, actor, action, note, after)
